import numpy as np

def track_provenance(dataset, sources, licenses):
    compatible_licenses = {'MIT', 'Apache', 'CC-BY', 'Public Domain', 'CC0'}
    report = {'total': len(dataset), 'tracked': 0, 'untracked': 0, 'incompatible': 0, 'flags': []}
    for i, data_id in enumerate(dataset):
        source = sources.get(data_id)
        license_type = licenses.get(data_id, 'unknown')
        if source is None:
            report['untracked'] += 1
            report['flags'].append(f'Data {i}: no source')
        elif license_type not in compatible_licenses:
            report['incompatible'] += 1
            report['flags'].append(f'Data {i}: incompatible license ({license_type})')
        else:
            report['tracked'] += 1
    return report
